import{_ as a,o as d,c as o,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"کاپی آئینہ دور دراز آثار قدیمہ اسکیم","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0085-复制镜异地考古方案.md","filePath":"ur/0085-复制镜异地考古方案.md"}'),e={name:"ur/0085-复制镜异地考古方案.md"};function l(h,t,i,u,n,q){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="کاپی-آئینہ-دور-دراز-آثار-قدیمہ-اسکیم" tabindex="-1">کاپی آئینہ دور دراز آثار قدیمہ اسکیم <a class="header-anchor" href="#کاپی-آئینہ-دور-دراز-آثار-قدیمہ-اسکیم" aria-label="Permalink to &quot;کاپی آئینہ دور دراز آثار قدیمہ اسکیم&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>85</td></tr><tr><td>ماڈیول</td><td>بین السطح تعامل اور وقت کے اصول</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>کاپی آئینہ، دور دراز آثار قدیمہ، جگہ اسکین، کاپی کی تعمیر نو، صفر رابطہ</td></tr></tbody></table><h2 id="_1-اسکیم-کا-خلاصہ" tabindex="-1">1. اسکیم کا خلاصہ <a class="header-anchor" href="#_1-اسکیم-کا-خلاصہ" aria-label="Permalink to &quot;1. اسکیم کا خلاصہ&quot;">​</a></h2><p>کاپی آئینہ دور دراز آثار قدیمہ اسکیم ہینگ یوان ژو کی بین السطح اور وقت کے پیچھے ہٹنے والی آثار قدیمہ کی معیاری تکنیکی اسکیم ہے، جس کا بنیادی خیال ہے &quot;داخل نہ ہوں، رابطہ نہ کرو، صرف کاپی کرو&quot;۔ روایتی آثار قدیمہ میں آثار قدیمہ کے اہلکاروں کو خود آثار قدیمہ کی جگہ پر داخل ہو کر کھدائی کرنی پڑتی ہے، جو لامحالہ جگہ پر جسمانی مداخلت اور ماحولیاتی آلودگی کا سبب بنتی ہے۔ کاپی آئینہ اسکیم جگہ کے قانونی ٹیکنالوجی کے ذریعے، اصل چیز سے مکمل طور پر رابطہ کیے بغیر، آثار قدیمہ کے ہدف کو مکمل طور پر دور دراز کی الگ تھلگ جگہ میں کاپی کرتا ہے، پھر الگ تھلگ جگہ کے اندر تمام آثار قدیمہ کے آپریشن انجام دیتا ہے۔</p><p>&quot;دور دراز&quot; اس اسکیم کی کلیدی خصوصیت ہے۔ کاپی کا آپریشن ہدف سطح یا ہدف مدت کے قریبی محفوظ علاقے میں مکمل ہوتا ہے، لیکن کاپی کی تخلیق اور بعد میں آثار قدیمہ کی تحقیق مکمل طور پر ہدف سے مکمل طور پر الگ تھلگ خودمختار جگہ میں کی جاتی ہے۔ اس کا مطلب ہے کہ آثار قدیمہ کے اہلکاروں کو شروع سے آخر تک ہدف علاقے میں داخل ہونے کی ضرورت نہیں ہے، یہاں تک کہ ہدف سطح میں داخل ہونے کی بھی ضرورت نہیں ہے — پوری آثار قدیمہ کے عمل کو اپنی سطح کی الگ تھلگ جگہ میں دور دراز طریقے سے مکمل کیا جا سکتا ہے۔</p><p>کاپی آئینہ دور دراز آثار قدیمہ اسکیم کی تکنیکی بنیاد جگہ قانونی ضابطے کے نظام کی اعلیٰ سطح کی اطلاق ہے۔ صرف جگہ قانونی ضابطے کے نظام کے چوتھے مرحلے (فا کونگ جِنگ) یا اس سے زیادہ سادھک، یا مساوی تکنیکی سطح کے کاپی آئینہ گاڑی کے ساتھ، ہی اعلیٰ درستگی کی کاپی آپریشن انجام دے سکتے ہیں۔ فی الحال ہینگ یوان ژو نے کاپی آئینہ کی انجینئرنگ بلک پروڈکشن کو عملی جامہ پہنا دیا ہے، معیاری قسم کے کاپی آئینہ ڈیوائس کو تیسرے مرحلے (ہوا کونگ جِنگ) کے سادھک کے ذریعے چلایا جا سکتا ہے تاکہ معمول کے آثار قدیمہ کے کام مکمل کیے جا سکیں۔</p><h2 id="_2-کاپی-آئینہ-کے-تکنیکی-اصول" tabindex="-1">2. کاپی آئینہ کے تکنیکی اصول <a class="header-anchor" href="#_2-کاپی-آئینہ-کے-تکنیکی-اصول" aria-label="Permalink to &quot;2. کاپی آئینہ کے تکنیکی اصول&quot;">​</a></h2><p>کاپی آئینہ کے بنیادی حصے ہیں &quot;جگہ قانون اسکین سرنی&quot; اور &quot;ذرہ کی حالت دوبارہ تعمیر کرنے والا&quot;۔ اس کے کام کا عمل تین مراحل میں تقسیم ہوتا ہے:</p><h3 id="_2-1-جگہ-اسکین-مرحلہ" tabindex="-1">2.1 جگہ اسکین مرحلہ <a class="header-anchor" href="#_2-1-جگہ-اسکین-مرحلہ" aria-label="Permalink to &quot;2.1 جگہ اسکین مرحلہ&quot;">​</a></h3><p>کاپی آئینہ کی تعیناتی مکمل ہونے کے بعد، سب سے پہلے ہدف علاقے پر ہر طرف سے جگہ قانون اسکین کیا جاتا ہے۔ اسکین سرنی ہائی فریکوئنسی جگہ لہریں خارج کرتی ہے، جو ہدف علاقے کے تمام مادے اور توانائی کے ڈھانچے کو گھیر لیتی ہے، ہر ذرہ کی پوزیشن، مومینٹم، اسپن، توانائی کی حالت جیسے تمام کوانٹم پیرامیٹرز ریکارڈ کرتی ہے۔ ایک ہی وقت میں، اسکین سرنی ہدف علاقے کے توانائی کے میدان کی تقسیم، قانونی پیرامیٹرز کے اتار چڑھاؤ اور شعور کے نشانات کی باقیات کا بھی پتہ لگاتی ہے۔</p><p>اسکین کا عمل مکمل طور پر غیر فعال ہے — جگہ لہریں مادے کو گھیرنے کے وقت اس کی کوئی حالت تبدیل نہیں کرتیں، اس لیے آثار قدیمہ کی جگہ پر کوئی مداخلت نہیں کرتیں۔ اسکین کی درستگی کاپی آئینہ کی تکنیکی سطح پر منحصر ہے، معیاری قسم کے ڈیوائس کی اسکین کی درستگی ذیلی ایٹم کی سطح ہے، اعلیٰ درجے کی تحقیقی قسم کا ڈیوائس کوارک کی سطح تک پہنچ سکتا ہے۔</p><h3 id="_2-2-ڈیٹا-ٹرانسمیشن-مرحلہ" tabindex="-1">2.2 ڈیٹا ٹرانسمیشن مرحلہ <a class="header-anchor" href="#_2-2-ڈیٹا-ٹرانسمیشن-مرحلہ" aria-label="Permalink to &quot;2.2 ڈیٹا ٹرانسمیشن مرحلہ&quot;">​</a></h3><p>اسکین سے حاصل ہونے والے بہت بڑے ڈیٹا کو اینکر نیٹ ورک کے انکرپٹڈ چینل کے ذریعے الگ تھلگ جگہ میں منتقل کیا جاتا ہے۔ ڈیٹا ٹرانسمیشن &quot;کوانٹم اسٹیٹ انکرپشن پروٹوکول&quot; استعمال کرتا ہے، اس بات کو یقینی بناتا ہے کہ ٹرانسمیشن کے عمل میں ڈیٹا چوری یا تبدیل نہیں ہوتا۔ ڈیٹا کی مقدار انتہائی زیادہ ہے — ایک عام کمرے کے سائز کے علاقے کے لیے، مکمل اسکین ڈیٹا کی مقدار تقریباً 10 کی 30 گھات بائٹ ہے، جسے مناسب وقت میں ٹرانسمیشن مکمل کرنے کے لیے اینکر نیٹ ورک کے ہائی ڈائمینشنل ڈیٹا چینل کی ضرورت ہوتی ہے۔</p><h3 id="_2-3-کاپی-کی-تعمیر-نو-مرحلہ" tabindex="-1">2.3 کاپی کی تعمیر نو مرحلہ <a class="header-anchor" href="#_2-3-کاپی-کی-تعمیر-نو-مرحلہ" aria-label="Permalink to &quot;2.3 کاپی کی تعمیر نو مرحلہ&quot;">​</a></h3><p>الگ تھلگ جگہ میں ذرہ کی حالت دوبارہ تعمیر کرنے والا ڈیٹا وصول کرنے کے بعد، اسکین ریکارڈ کے عین مطابق پیرامیٹرز کے مطابق، الگ تھلگ جگہ میں ذرہ بہ ذرہ ہدف علاقے کی مکمل کاپی دوبارہ بناتا ہے۔ تعمیر نو کا عمل نچلی تہہ کے ذرہ سے شروع ہوتا ہے، تہہ در تہہ اوپر کی طرف ایٹم، مالیکیول، مادے کا ڈھانچہ، توانائی کا میدان اور شعور کے نشانات بناتا ہے۔ تعمیر نو مکمل ہونے کے بعد، کاپی اور اصل چیز جسمانی سطح پر بالکل مماثل ہیں — آثار قدیمہ کی چیزوں کا مواد، ڈھانچہ، سطح کے نشانات، اندرونی نقصان، یہاں تک کہ باقی توانائی کا میدان اور شعور کے نشانات سمیت۔</p><p>خاص طور پر بتانا ضروری ہے کہ کاپی میں موجود &quot;شعور کے نشانات&quot; اصل چیز کی طویل وجود کے عمل میں جذب کردہ ماحولیاتی شعور کی باقیات ہیں، حقیقی شعور کی چیز نہیں ہیں۔ کاپی میں خود مختار شعور نہیں ہے، اور کوئی نئی شعور کی سرگرمی بھی پیدا نہیں کرے گا۔ اس بات کی سمبیوسس عدالت کی قانونی تشریح کے ذریعے تصدیق ہو چکی ہے، کاپی &quot;زندگی&quot; کے زمرے میں نہیں آتی، کاپی کی تحقیق میں زندگی کے اخلاقی مسائل شامل نہیں ہیں۔</p><h2 id="_3-کاپی-آئینہ-کی-درجہ-بندی-اور-لاگو-منظرنامے" tabindex="-1">3. کاپی آئینہ کی درجہ بندی اور لاگو منظرنامے <a class="header-anchor" href="#_3-کاپی-آئینہ-کی-درجہ-بندی-اور-لاگو-منظرنامے" aria-label="Permalink to &quot;3. کاپی آئینہ کی درجہ بندی اور لاگو منظرنامے&quot;">​</a></h2><p>کاپی کی حد، درستگی اور فعالیت کے مطابق، کاپی آئینہ درج ذیل چار اقسام میں تقسیم ہوتا ہے:</p><table tabindex="0"><thead><tr><th>ماڈل</th><th>کاپی کی حد</th><th>درستگی کی سطح</th><th>لاگو منظرنامہ</th><th>آپریٹر کی سادھک کی ضرورت</th></tr></thead><tbody><tr><td>معیاری قسم (CM-S)</td><td>زیادہ سے زیادہ 100 مکعب میٹر</td><td>ذیلی ایٹم کی سطح</td><td>واحد آثار قدیمہ کی چیز، چھوٹے کھنڈرات کی معمول کے آثار قدیمہ</td><td>ہوا کونگ جِنگ (تیسرا مرحلہ)</td></tr><tr><td>توسیعی قسم (CM-E)</td><td>زیادہ سے زیادہ 10000 مکعب میٹر</td><td>ذیلی ایٹم کی سطح</td><td>بڑی عمارت، گاؤں کی سطح کے کھنڈرات کی مکمل کاپی</td><td>فا کونگ جِنگ (چوتھا مرحلہ)</td></tr><tr><td>تحقیقی قسم (CM-R)</td><td>زیادہ سے زیادہ 1000 مکعب میٹر</td><td>کوارک کی سطح</td><td>انتہائی اعلیٰ درستگی کے تجزیے کی ضرورت والی قیمتی آثار قدیمہ کی چیزوں کی تحقیق</td><td>فا کونگ جِنگ (چوتھا مرحلہ)+ ڈیڈکشن ایٹریشن نظام کا تیسرا مرحلہ</td></tr><tr><td>خصوصی قسم (CM-X)</td><td>زیادہ سے زیادہ 1 مکعب کلومیٹر</td><td>ذیلی ایٹم کی سطح</td><td>شہر کی سطح کے کھنڈرات کے گروپ کی بچاؤ کی مکمل کاپی</td><td>یوان کونگ جِنگ (پانچواں مرحلہ) یا گاڑی کی مدد</td></tr></tbody></table><p>قانون ٹوٹی سطح جیسے خاص ماحول کے لیے، خاص طور پر تبدیل کردہ &quot;قانون مطابقت پذیر کاپی آئینہ&quot; استعمال کرنے کی ضرورت ہے، جس کی اسکین سرنی غیر مستحکم قانونی ماحول کے ساتھ ڈھال لے سکتی ہے، اس بات کو یقینی بناتی ہے کہ قانون کے اتار چڑھاؤ کے درمیان بھی درست اسکین ڈیٹا حاصل کیا جا سکے۔</p><h2 id="_4-دور-دراز-آثار-قدیمہ-کے-آپریشن-کے-اہم-نکات" tabindex="-1">4. دور دراز آثار قدیمہ کے آپریشن کے اہم نکات <a class="header-anchor" href="#_4-دور-دراز-آثار-قدیمہ-کے-آپریشن-کے-اہم-نکات" aria-label="Permalink to &quot;4. دور دراز آثار قدیمہ کے آپریشن کے اہم نکات&quot;">​</a></h2><p>کاپی آئینہ دور دراز آثار قدیمہ اسکیم کو عملی آپریشن میں درج ذیل اہم نکات پر توجہ دینے کی ضرورت ہے:</p><ol><li><p><strong>تعیناتی جگہ کا انتخاب</strong>: کاپی آئینہ کو ہدف علاقے کے قانونی محفوظ فاصلے سے باہر تعینات کرنا چاہیے، جو既 اس بات کو یقینی بناتا ہے کہ اسکین کی حد ہدف کو کور کرے،又 ڈیوائس خود ہدف علاقے میں قانونی خلل پیدا کرنے سے بچے۔ محفوظ فاصلہ عام طور پر ہدف علاقے کے زیادہ سے زیادہ سائز کا 3 گنا یا اس سے زیادہ ہوتا ہے۔</p></li><li><p><strong>کاپی کے وقت کا انتخاب</strong>: وقت کے پیچھے ہٹنے والی آثار قدیمہ کے لیے، کاپی آئینہ کی تعیناتی اور اسکین کو ہدف مدت کے &quot;قانونی سکون کے دور&quot; میں انجام دینا چاہیے، بڑے تاریخی واقعات کے وقت کاپی آپریشن انجام دینے سے گریز کریں — اس وقت وجوہاتی زنجیر کی کثافت انتہائی زیادہ ہوتی ہے، کاپی آپریشن کی توانائی کی کھپت نمایاں طور پر بڑھ جاتی ہے، اور وجوہاتی لائن میں کمزور خلل پیدا کر سکتی ہے۔</p></li><li><p><strong>کاپی کی مکملیت کی تصدیق</strong>: کاپی کی تعمیر نو مکمل ہونے کے بعد، ضروری ہے کہ &quot;کاپی-اصل چیز کی مطابقت کی تصدیق&quot; انجام دیا جائے۔ تصدیق کا طریقہ یہ ہے کہ کاپی کا دوسرا اسکین کیا جائے، اسکین ڈیٹا کو اصل اسکین ڈیٹا سے ذرہ بہ ذرہ موازنہ کیا جائے، خرابی کی شرح 10 کی منفی 12 گھات سے کم ہونی چاہیے۔ اگر خرابی کی شرح حد سے تجاوز کر جائے تو کاپی کو تباہ کر کے دوبارہ کاپی کرنا ضروری ہے۔</p></li><li><p><strong>کئی راؤنڈ کاپی کی حکمت عملی</strong>: بہت بڑے کھنڈرات کے لیے، ایک بار کی کاپی پورے علاقے کو کور نہ کر سکتی ہے۔ اس وقت &quot;علاقہ وار کئی راؤنڈ کاپی&quot; کی حکمت عملی اختیار کی جاتی ہے، کھنڈرات کو متعدد علاقوں میں تقسیم کر کے الگ الگ کاپی کیا جاتا ہے، پھر الگ تھلگ جگہ میں جوڑا جاتا ہے۔ جوڑتے وقت اس بات کو یقینی بنانا ضروری ہے کہ ملحقہ علاقوں کی سرحد پر ذرہ کی حالت بغیر کسی خلل کے جڑ جائے، کوئی قانونی خرابی نہیں آئے گی۔</p></li></ol><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>کاپی آئینہ دور دراز آثار قدیمہ اسکیم ہینگ یوان ژو کی طرف سے جگہ کے قانونی قوانین کی انجینئرنگ اطلاق کا نمونہ ہے۔ یہ &quot;صفر رابطہ کاپی، دور دراز تحقیق&quot; کے تکنیکی راستے کے ذریعے، بنیادی طور پر روایتی آثار قدیمہ میں &quot;علم حاصل کرنے&quot; اور &quot;جگہ کی حفاظت&quot; کے درمیان تضاد کو حل کرتا ہے۔ یہ اسکیم نہ صرف آثار قدیمہ کی کارکردگی کو نمایاں طور پر بڑھاتی ہے، بلکہ اس سے بھی زیادہ اہم بات یہ ہے کہ یہ اس بات کو یقینی بناتی ہے کہ ہر آثار قدیمہ ہدف تہذیب اور تاریخی جگہ پر کوئی نشان نہیں چھوڑتی — حقیقی معنوں میں &quot;آہستہ سے میں چلا گیا، جیسا کہ میں آہستہ سے آیا تھا&quot;۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>84-آثار قدیمہ پروٹوکول کا عمومی خاکہ</li><li>86-الگ تھلگ جگہ کم آلودگی کا عمل</li><li>63-کاپی آئینہ تکنیکی اصول</li></ul>',27)])])}const s=a(e,[["render",l]]);export{p as __pageData,s as default};
